#!/usr/bin/env node
// Generated by OrchestKit Claude Plugin
// Created: 2026-10-31
/**
 * check-dispatch-proof.mjs: did every folded handler run, exactly once?
 *
 * Reads a `claude --debug-file` log from a session run with the flag-on
 * hooks.json and ORK_DISPATCH_PROOF=1 (see src/lib/dispatch-proof.ts). Each
 * dispatcher run leaves one "Hooks: Parsed initial response: {json}" line
 * whose systemMessage carries one ork-proof:<event>:<tool>:<id>@ok|failed
 * token per handler it ran.
 *
 * For every such run it compares the tokens with the handlers the SHIPPED
 * hooks.json launches for that event and tool (identical commands counted
 * once, as CC does):
 *   - each expected handler must appear exactly once (zero or two fails)
 *   - no unexpected handler may appear
 *   - every outcome must be ok, except the --break handler, which must be
 *     failed in every run that routes to it
 * It also fails when a --require'd event:tool pair has no run at all.
 *
 * Usage:
 *   node scripts/check-dispatch-proof.mjs <debug.log> [--hooks hooks.json]
 *        [--break <handler-id>] [--require PreToolUse:Bash,PostToolUse:Edit]
 */
import { readFileSync } from 'node:fs';
import { join, dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const PROOF_RE = /ork-proof:([A-Za-z]+):([^:\s"\\]+):([^\s"\\]+?)@(ok|failed)/g;

export function matches(matcher, tool) {
  if (matcher === undefined || matcher === '' || matcher === '*') return true;
  if (/^[\w|-]+$/.test(matcher)) return matcher.split('|').includes(tool);
  return new RegExp(matcher).test(tool);
}

/** Handler ids the shipped hooks.json launches for one event and tool. */
export function expectedIds(hooksDoc, event, tool) {
  const ids = [];
  for (const group of hooksDoc.hooks?.[event] ?? []) {
    if (!matches(group.matcher, tool)) continue;
    for (const h of group.hooks ?? []) {
      const id = h.args?.[1];
      if (h.type === 'command' && id && !ids.includes(id)) ids.push(id);
    }
  }
  return ids;
}

/** One entry per dispatcher run that printed proof tokens. */
export function proofRuns(logText) {
  const runs = [];
  for (const line of logText.split('\n')) {
    if (!line.includes('Parsed initial response:') || !line.includes('ork-proof:')) continue;
    const tokens = [...line.matchAll(PROOF_RE)].map((m) => ({ event: m[1], tool: m[2], id: m[3], outcome: m[4] }));
    // CC's debug logger masks `<word with secret/token/key>=<value>`; a masked
    // token is a logging artifact, reported by name rather than as "seen 0".
    const redacted = [...line.matchAll(/ork-proof:[^\s"\\]*\[REDACTED\]/g)].map((m) => m[0]);
    if (tokens.length) runs.push({ event: tokens[0].event, tool: tokens[0].tool, tokens, redacted });
  }
  return runs;
}

export function judge(runs, hooksDoc, { breakId, require = [] } = {}) {
  const problems = [];
  const report = [];
  // An empty log proves nothing: a flag-on session with no proof tokens means
  // the dispatchers never ran (or proof mode was off), not that all is well.
  if (!runs.length) problems.push('no dispatcher run with proof tokens in the log (flag off, or ORK_DISPATCH_PROOF unset?)');
  for (const run of runs) {
    const expected = expectedIds(hooksDoc, run.event, run.tool);
    const counts = new Map();
    for (const t of run.tokens) counts.set(t.id, (counts.get(t.id) ?? 0) + 1);
    const where = `${run.event}:${run.tool}`;
    for (const r of run.redacted ?? []) problems.push(`${where} redacted by the debug logger: ${r}`);
    for (const id of expected) {
      const n = counts.get(id) ?? 0;
      if (n !== 1) problems.push(`${where} ${id}: seen ${n} times, want exactly 1`);
    }
    for (const id of counts.keys()) {
      if (!expected.includes(id)) problems.push(`${where} ${id}: ran but the shipped hooks.json does not launch it here`);
    }
    for (const t of run.tokens) {
      const want = t.id === breakId ? 'failed' : 'ok';
      if (t.outcome !== want) problems.push(`${where} ${t.id}: ${t.outcome}, want ${want}`);
    }
    const failed = run.tokens.filter((t) => t.outcome === 'failed').length;
    report.push(`${where.padEnd(18)} expected ${String(expected.length).padStart(2)}  seen ${String(run.tokens.length).padStart(2)}  failed ${failed}`);
  }
  for (const pair of require) {
    if (!runs.some((r) => `${r.event}:${r.tool}` === pair)) problems.push(`${pair}: no dispatcher run with proof tokens in the log`);
  }
  if (breakId && !runs.some((r) => r.tokens.some((t) => t.id === breakId && t.outcome === 'failed'))) {
    problems.push(`--break ${breakId}: never showed as failed`);
  }
  return { problems, report };
}

function arg(name, fallback) {
  const i = process.argv.indexOf(name);
  return i > -1 ? process.argv[i + 1] : fallback;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const here = dirname(fileURLToPath(import.meta.url));
  const log = process.argv[2];
  if (!log || log.startsWith('--')) {
    console.error('usage: check-dispatch-proof.mjs <debug.log> [--hooks hooks.json] [--break <id>] [--require a:b,c:d]');
    process.exit(2);
  }
  const hooksDoc = JSON.parse(readFileSync(resolve(arg('--hooks', join(here, '..', 'hooks.json'))), 'utf8'));
  const require = (arg('--require', '') || '').split(',').filter(Boolean);
  const { problems, report } = judge(proofRuns(readFileSync(log, 'utf8')), hooksDoc, { breakId: arg('--break'), require });
  console.log(report.join('\n'));
  for (const p of problems) console.log(`FAIL ${p}`);
  console.log(problems.length ? `check-dispatch-proof: FAIL (${problems.length})` : 'check-dispatch-proof: OK');
  process.exit(problems.length ? 1 : 0);
}
